570: std::string VlmTaskPlanner::plan_request(
571:   const std::string & cmd, const TrackedObjectArray & objs, const ReplanInfo & rp,
572:   const std::vector<ImageFrame> & imgs, const RobotPose & robot) {
573:   std::string o = "{\"command\": \"" + json_escape(cmd) + "\", \"objects\": [";
574:   bool first = true;
575:   for (const auto & obj : objs.objects) {
576:     if (!first) o += ", ";
577:     first = false;
578:     char pos[128], size[128];
579:     snprintf(pos, sizeof(pos), "[%.3f, %.3f, %.3f]",
580:       obj.pose.pose.position.x, obj.pose.pose.position.y, obj.pose.pose.position.z);
581:     snprintf(size, sizeof(size), "[%.3f, %.3f, %.3f]", obj.size.x, obj.size.y, obj.size.z);
582:     char conf[16];
583:     snprintf(conf, sizeof(conf), "%.2f", obj.confidence);
584:     const std::string cam = obj.cameras.empty() ? std::string() : obj.cameras.back();  // 마지막으로 본 카메라 (px의 카메라)
585:     char px[64];  // ai-service 형식 {카메라: [u, v]} — 예전 [u, v]만 보내서 images.py가 번호를 못 찍었음
586:     snprintf(px, sizeof(px), "[%d, %d]", obj.px[0], obj.px[1]);
587:     o += std::string("{\"id\": ") + std::to_string(obj.id) + ", \"class_name\": \"" +
588:       json_escape(obj.class_name) + "\", \"position\": " + pos + ", \"size\": " + size +
589:       ", \"confidence\": " + conf + ", \"color\": \"" + json_escape(obj.color) +
590:       "\", \"camera\": \"" + json_escape(cam) + "\", \"px\": " +
591:       (cam.empty() ? std::string("{}") : "{\"" + json_escape(cam) + "\": " + px + "}");
592:     for (const char * key : {"tag", "content", "posture"}) {  // 퍽 번호 · 장소 태그 · 바코드 작업 지시 · 자세
593:       const std::string v = detail(obj, key);
594:       if (!v.empty()) o += std::string(", \"") + key + "\": \"" + json_escape(v) + "\"";
595:     }
596:     o += "}";
597:   }
598:   o += "]";
599:   if (robot.ok) {
600:     char rb[160];
601:     snprintf(rb, sizeof(rb), ", \"robot\": {\"x\": %.3f, \"y\": %.3f, \"yaw\": %.3f}", robot.x, robot.y, robot.yaw);
602:     o += rb;
603:   }
604:   if (rp.active) {
605:     o += ", \"replan\": {\"plan_id\": " + std::to_string(rp.plan_id) + ", \"failed_step\": " +
606:       std::to_string(rp.step) + ", \"reason\": \"" + json_escape(rp.reason) + "\"}";
607:   }
608:   o += ", \"images\": [";
609:   bool ifirst = true;
610:   for (const auto & im : imgs) {
611:     if (!im.msg) continue;
612:     const std::string b64 = encode_jpeg_base64(*im.msg);
613:     if (b64.empty()) continue;
614:     if (!ifirst) o += ", ";
615:     ifirst = false;
616:     o += "{\"camera\": \"" + im.camera + "\", \"format\": \"jpeg\", \"data_b64\": \"" + b64 + "\"}";
617:   }
618:   o += "]";
619:   return o + "}";

251: bool parse_goals(const std::string & body, std::vector<SubGoal> & goals, std::string * err = nullptr) {
252:   Cursor c{body.c_str()};
253:   c.ws();
254:   if (*c.p != '{') return false;
255:   const char * ok = std::strstr(c.p, "\"ok\"");
256:   if (!ok) return false;
257:   c.p = ok + 4;
258:   c.ws();
259:   if (*c.p != ':') return false;
260:   ++c.p;
261:   c.ws();
262:   if (std::strncmp(c.p, "true", 4) != 0) {  // ok:false → 에러문 추출 (say 계획으로 보여줌)
263:     if (err) {
264:       const char * e = std::strstr(c.p, "\"error\"");
265:       if (e) {
266:         Cursor ec{e + 7};
267:         ec.ws();
268:         if (*ec.p == ':') { ++ec.p; ec.ws(); ec.str(*err); }
269:       }
270:     }
271:     return false;
272:   }
273:   const char * g = std::strstr(c.p, "\"goals\"");
274:   if (!g) return false;
275:   c.p = g + 7;
276:   c.ws();
277:   if (*c.p != ':') return false;
278:   ++c.p;
279:   c.ws();
280:   if (*c.p != '[') return false;
281:   ++c.p;
282:   static const std::set<std::string> allowed = {"navigate", "pick", "place", "say"};
283:   uint32_t step = 0;
284:   for (;;) {
285:     c.ws();
286:     if (*c.p == ']') return !goals.empty();
287:     if (*c.p != '{') return false;
288:     ++c.p;
289:     SubGoal sg;
290:     uint32_t got_step = 0;
291:     bool has_step = false, has_skill = false;
292:     for (;;) {
293:       c.ws();
294:       if (*c.p == '}') { ++c.p; break; }
295:       std::string k;
296:       if (!c.str(k)) return false;
297:       c.ws();
298:       if (*c.p != ':') return false;
299:       ++c.p;
300:       c.ws();
301:       if (k == "step") {
302:         double v;
303:         if (!c.num(v)) return false;
304:         got_step = static_cast<uint32_t>(v);
305:         has_step = true;
306:       } else if (k == "skill" || k == "target" || k == "relation") {
307:         std::string v;
308:         if (*c.p == '"') {
309:           if (!c.str(v)) return false;
310:         } else {  // target이 숫자면 문자열로
311:           double n;
312:           if (!c.num(n)) return false;
313:           v = std::to_string(static_cast<long long>(n));
314:         }
315:         if (k == "skill") { sg.skill = v; has_skill = true; }
316:         else if (k == "target") sg.target = v;
317:         else sg.relation = v;
318:       } else if (k == "offset_m") {
319:         double v;
320:         if (!c.num(v)) return false;
321:         sg.offset_m = static_cast<float>(v);
322:       } else {
323:         if (!c.skip()) return false;
324:       }
325:       c.ws();
326:       if (*c.p == ',') { ++c.p; continue; }
327:       if (*c.p == '}') continue;  // 루프 head에서 닫음
328:       return false;
329:     }
330:     if (!has_step || !has_skill || got_step != ++step || !allowed.count(sg.skill)) return false;
331:     sg.step = got_step;
332:     goals.push_back(sg);
333:     c.ws();
334:     if (*c.p == ',') { ++c.p; continue; }
335:     if (*c.p == ']') return !goals.empty();
336:     return false;
337:   }
338: }

