18: void FakeLocalizer::on_truth(const geometry_msgs::msg::PoseStamped & truth) {
19:   geometry_msgs::msg::TransformStamped odom_base;
20:   try {
21:     odom_base = tf_buffer_->lookupTransform("odom", "base_footprint", tf2::TimePointZero);
