28:   geometry_msgs::msg::TransformStamped out;
29:   out.header.stamp = now();
30:   out.header.frame_id = "map";
31:   out.child_frame_id = "odom";
32:   out.transform = tf2::toMsg(map_base * odom_base_t.inverse());
33:   tf_pub_->sendTransform(out);
34: }

